    facts: {
      de: ["Der Name Kanas bedeutet 'schön und reich, geheimnisvoll' auf Mongolisch.", "Der See wurde durch Gletscheraktivität geformt.", "Die umliegende Landschaft ist eine Mischung aus sibirischer Taiga und zentralasiatischer Steppe."],
      hu: ["A Kanas név mongolul azt jelenti: 'szép és gazdag, titokzatos'.", "A tavat gleccsertevékenység alakította ki.", "A környező táj a szibériai tajga és a közép-ázsiai sztyeppe keveréke."],
      ro: ["Numele Kanas înseamnă 'frumos și bogat, misterios' în mongolă.", "Lacul a fost format de activitatea glaciară.", "Peisajul înconjurător este un amestec de taiga siberiană și stepă central-asiatică."],
      en: ["The name Kanas means 'beautiful and rich, mysterious' in Mongolian.", "The lake was formed by glacier activity.", "The surrounding landscape is a mix of Siberian taiga and Central Asian steppe."],
      es: ["El nombre Kanas significa 'hermoso y rico, misterioso' en mongol.", "El lago se formó por la actividad glaciar.", "El paisaje circundante es una mezcla de taiga siberiana y estepa centroasiática."],
      pt: ["O nome Kanas significa 'bonito e rico, misterioso' em mongol.", "O lago foi formado pela atividade glaciar.", "A paisagem circundante é uma mistura de taiga siberiana e estepe centro-asiática."],
      fr: ["Le nom Kanas signifie 'beau, riche et mystérieux' en mongol.", "Le lac a été formé par l'activité glaciaire.", "Le paysage environnant est un mélange de taïga sibérienne et de steppe d'Asie centrale."],
    },
    descriptionAdvanced: {
      de: "Der Kanas-See liegt im Altai-Gebirge in der Präfektur Altay im Norden des Autonomen Gebiets Xinjiang, China. Er ist bekannt für seine außergewöhnliche natürliche Schönheit, die oft mit der Landschaft der Schweizer Alpen verglichen wird. Der See hat eine Fläche von etwa 45,7 Quadratkilometern und eine maximale Tiefe von 188,5 Metern, was ihn zu einem der tiefsten Alpenseen Chinas macht. Seine sichelförmige Gestalt und das milchig-türkisfarbene Wasser, das je nach Jahreszeit seine Farbe ändert, ziehen jährlich Tausende von Besuchern an. Umgeben ist der See von dichten sibirischen Lärchen- und Fichtenwäldern, die Teil eines ausgedehnten Naturschutzgebietes sind. In der Region leben die Tuva, eine mongolische ethnische Minderheit, die ihre traditionelle Lebensweise in Holzhütten und ihre einzigartige Kehlkopfgesangs-Kultur bewahrt hat. Ein bekanntes lokales Mysterium ist das „Kanas-See-Monster“, bei dem es sich laut Wissenschaftlern um riesige Huchen-Fische handeln könnte. Der See friert im Winter vollständig zu und bietet dann eine spektakuläre Eislandschaft.",
      hu: "A Kanasz-tó az Altaj-hegységben található, Hszincsiang tartomány északi részén, Kínában. Különleges természeti szépségéről ismert, amelyet gyakran a Svájci Alpok tájaihoz hasonlítanak. A tó felszíne körülbelül 45,7 négyzetkilométer, maximális mélysége pedig 188,5 méter, amivel Kína egyik legmélyebb alpesi tavának számít. Kifli alakja és tejfehér-türkizkék vize, amely az évszakok függvényében változtatja a színét, turisták ezreit vonzza évente. A tavat sűrű szibériai vörösfenyő- és lucfenyőerdők övezik, amelyek egy kiterjedt természetvédelmi terület részét képezik. A régióban élnek a tuvák, egy mongol etnikai kisebbség, akik megőrizték hagyományos életmódjukat faházaikban és egyedülálló torokéneklési kultúrájukat. Helyi legenda övezi a „Kanasz-tavi szörnyet”, amelyről a tudósok úgy vélik, hogy valójában hatalmas méretű dunai galócák lehetnek. Télen a tó teljesen befagy, lenyűgöző jégvilágot teremtve.",
      ro: "Lacul Kanas este situat în Munții Altai, în prefectura Altay din nordul regiunii autonome Xinjiang, China. Este renumit pentru frumusețea sa naturală excepțională, fiind adesea comparat cu peisajele Alpilor Elvețieni. Lacul are o suprafață de aproximativ 45,7 kilometri pătrați și o adâncime maximă de 188,5 metri, fiind unul dintre cele mai adânci lacuri alpine din China. Forma sa de semilună și apa de un turcoaz lăptos, care își schimbă nuanța în funcție de anotimp, atrag anual mii de vizitatori. Lacul este înconjurat de păduri dese de lariță siberiană și molid, care fac parte dintr-o rezervație naturală extinsă. În regiune trăiesc etnicii Tuva, o minoritate mongolă care și-a păstrat modul tradițional de viață în cabane de lemn și cultura unică a cântatului din gât. Un mister local celebru este „monstrul din lacul Kanas”, despre care cercetătorii cred că ar putea fi de fapt exemplare uriașe de pești hucho hucho. Iarna, lacul îngheață complet, oferind un peisaj spectaculos de gheață.",
      en: "Kanas Lake is located in the Altai Mountains of northern Xinjiang, China, near the borders of Russia, Kazakhstan, and Mongolia. It is renowned for its exceptional natural beauty, often compared to the landscapes of the Swiss Alps. The lake covers an area of approximately 45.7 square kilometers and has a maximum depth of 188.5 meters, making it one of the deepest alpine lakes in China. Its crescent shape and milky-turquoise water, which changes color throughout the seasons, draw thousands of visitors annually. Surrounded by dense Siberian larch and spruce forests, the lake is part of a vast nature reserve protecting unique biodiversity. The region is home to the Tuva people, a Mongolian ethnic minority who preserve a traditional lifestyle in wooden cabins and a unique throat-singing culture. A famous local legend speaks of the \"Kanas Lake Monster,\" which scientists suggest may actually be giant Hucho taimen fish. In winter, the lake freezes completely, turning the area into a spectacular snowy wilderness.",
      es: "El lago Kanas, en la región autónoma de Xinjiang, se encuentra en las montañas Altai a una altitud de 1.374 metros. Su superficie es de 44,78 kilómetros cuadrados y su profundidad máxima de 188,5 metros. El lago es conocido por sus aguas turquesas y la leyenda de un monstruo lacustre. El lago está rodeado de densos bosques y forma parte de la Reserva Natural de Kanas. La región alberga a la etnia Tuva. El lago se congela en invierno de noviembre a mayo. La temperatura del agua alcanza un máximo de 15 grados Celsius en verano. El lago Kanas es un destino popular para los fotógrafos.",
      pt: "O lago Kanas, na Região Autônoma de Xinjiang, situa-se nas montanhas Altai a uma altitude de 1.374 metros. A área é de 44,78 quilômetros quadrados e a profundidade máxima é de 188,5 metros. O lago é conhecido pelas suas águas azul-turquesa e pela lenda de um monstro marinho. O lago está rodeado por florestas densas e faz parte da Reserva Natural de Kanas. A região abriga a etnia Tuva. O lago congela no inverno de novembro a maio. A temperatura da água atinge no máximo 15 graus Celsius no verão. O lago Kanas é um destino popular para fotógrafos.",
      fr: "Le lac Kanas, dans la région autonome du Xinjiang, est niché dans les monts Altaï à une altitude de 1 374 mètres. Sa superficie est de 44,78 km² et sa profondeur maximale de 188,5 mètres. Le lac est célèbre pour ses eaux turquoise et la légende d'un monstre lacustre. Il est entouré de forêts denses et fait partie de la réserve naturelle de Kanas. La région abrite l'ethnie Touva. Le lac gèle en hiver de novembre à mai. La température de l'eau atteint au maximum 15 °C en été. Le lac Kanas est une destination prisée des photographes.",
    },
