      de: ["Maximale Tiefe des Sees beträgt 188,5 Meter", "Gelegen im Altai-Gebirge auf einer Höhe von 1.374 Metern", "Sichelförmiger See mit einer Länge von etwa 24 Kilometern", "Heimat der mongolischen Tuva-Minderheit", "Berühmt für das angebliche 'Kanas-See-Monster'", "Wassertemperatur bleibt auch im Sommer meist unter 10 °C"],
