      en: ["Maximum depth of the lake reaches 188.5 meters", "Located in the Altai Mountains at an elevation of 1,374 meters", "Crescent-shaped lake with a length of about 24 kilometers", "Home to the Mongolian Tuva ethnic minority", "Famous for the legendary 'Kanas Lake Monster' sightings", "Water temperature typically stays below 10 °C even in summer"],
      es: ["El lago Kanas se encuentra a 1.374 metros de altitud.", "Su superficie es de 44,78 kilómetros cuadrados.", "La profundidad máxima es de 188,5 metros.", "El lago se congela de noviembre a mayo.", "La temperatura del agua alcanza un máximo de 15 grados Celsius.", "El lago es conocido por un monstruo lacustre."],
