      fr: ["Le lac Kanas est situé à 1 374 mètres d'altitude.", "Sa superficie est de 44,78 kilomètres carrés.", "Sa profondeur maximale est de 188,5 mètres.", "Le lac est gelé de novembre à mai.", "La température de l'eau atteint au maximum 15 degrés Celsius.", "Le lac est célèbre pour son monstre lacustre."],
